export function deText(value, lang) {
  return lang === "de" ? GERMAN_COPY[value] || value : value;
}

export function localizeGermanValue(value, lang) {
  if (lang !== "de") return value;
  if (typeof value === "string") return deText(value, lang);
  if (Array.isArray(value)) return value.map((item) => localizeGermanValue(item, lang));
  if (value && typeof value === "object") {
    return Object.fromEntries(
      Object.entries(value).map(([key, item]) => [key, localizeGermanValue(item, lang)])
    );
  }
  return value;
}
